with filtered_web_events as (select * from web_events where page = '/checkout'), event_type_group_summary as (select case when event_type in ('page_view', 'add_to_cart') then 'group_a' else 'other' end as event_type_group, sum(duration_sec) as total_duration_sec, max(event_time) as latest_event_time from filtered_web_events group by case when event_type in ('page_view', 'add_to_cart') then 'group_a' else 'other' end) select * from event_type_group_summary where total_duration_sec > 1400 order by total_duration_sec desc
